from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == grid[r][c]:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if not any(y == 0 or y == h-1 or x == 0 or x == w-1 for y,x in comp):
                continue
            minr, maxr = min(y for y,x in comp), max(y for y,x in comp)
            minc, maxc = min(x for y,x in comp), max(x for y,x in comp)
            # Border bars project perpendicular to their long axis. A corner singleton
            # uses a horizontal ray, as in the examples.
            vertical_ray = (maxc-minc) > (maxr-minr)
            if maxc == minc and maxr == minr:
                vertical_ray = False
            if vertical_ray:
                x = minc
                if minr == 0:
                    y, dy = minr, 1
                elif maxr == h-1:
                    y, dy = maxr, -1
                else:
                    continue
                while 0 <= y+dy < h:
                    y += dy
                    if grid[y][x] != bg:
                        out[y][x] = 4
                        break
                    out[y][x] = next(v for row in grid for v in row if v != bg and not (0 <= v <= 9 and v == grid[r][c])) if False else 0
            else:
                y = minr
                if minc == 0:
                    x, dx = minc, 1
                elif maxc == w-1:
                    x, dx = maxc, -1
                else:
                    continue
                while 0 <= x+dx < w:
                    x += dx
                    if grid[y][x] != bg:
                        out[y][x] = 4
                        break
